const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = item.props;

  // The ring draws itself, then the label follows. A ring that simply appears
  // reads as a sticker; one that draws reads as someone pointing.
  const draw = interpolate(frame, [fps * 0.15, fps * 0.7], [0, 1], { extrapolateRight: 'clamp' });
  const labelIn = interpolate(frame, [fps * 0.6, fps * 0.95], [0, 1], { extrapolateRight: 'clamp' });

  const width = item.width;
  const height = item.height;
  // `Number(undefined)` is NaN, not nullish, so `?? 0.5` would never fire and the
  // ring would land at NaN — invisible. Check for a finite number instead.
  const num = (value, fallback) => (Number.isFinite(Number(value)) ? Number(value) : fallback);
  const clamp01 = (value) => Math.min(1, Math.max(0, value));

  // Short side, not width: a ring sized from the width covers 71% of a 16:9
  // frame's height at the same fraction, which is never what "circle this" means.
  const size = Math.min(width, height) * Math.min(1, Math.max(0.12, num(p.size, 0.4)));
  const cx = width * clamp01(num(p.x, 0.5));
  const cy = height * clamp01(num(p.y, 0.5));
  const stroke = p.strokeWidth ?? 6;

  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor: p.bg || 'transparent',
  };

  // A rounded box traces its outline; a circle uses the dash trick so both
  // shapes reveal in the same gesture.
  const circumference = 2 * Math.PI * (size / 2);
  const boxLength = size * 4;

  return (
    <div style={rootStyle}>
      <svg width={width} height={height} style={{ position: 'absolute', inset: 0, overflow: 'visible' }}>
        {p.shape === 'box' ? (
          <rect
            x={cx - size / 2} y={cy - size / 2} width={size} height={size}
            rx={size * 0.08}
            fill="none" stroke={p.accent} strokeWidth={stroke}
            strokeDasharray={boxLength} strokeDashoffset={boxLength * (1 - draw)}
          />
        ) : (
          <circle
            cx={cx} cy={cy} r={size / 2}
            fill="none" stroke={p.accent} strokeWidth={stroke}
            strokeDasharray={circumference} strokeDashoffset={circumference * (1 - draw)}
          />
        )}
      </svg>
      {p.label ? (
        <div
          style={{
            position: 'absolute',
            left: cx,
            top: cy + size / 2 + 26,
            transform: 'translateX(-50%)',
            opacity: labelIn,
            fontFamily: p.bodyFont,
            fontSize: p.fontSize,
            color: p.ink,
            whiteSpace: 'nowrap',
            // A dark pill keeps the label readable over whatever it is pointing at.
            backgroundColor: 'rgba(11,11,12,0.72)',
            padding: '10px 22px',
            borderRadius: 8,
          }}
        >
          {p.label}
        </div>
      ) : null}
    </div>
  );
};

const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = item.props;

  const enter = spring({ frame, fps, config: { damping: 20, mass: 0.6, stiffness: 140 } });

  const a = Number(p.aValue);
  const b = Number(p.bValue);
  const safeA = Number.isFinite(a) ? a : 0;
  const safeB = Number.isFinite(b) ? b : 0;
  // Bars are scaled against the larger value, so the comparison is read as a
  // ratio rather than as two numbers the viewer has to divide in their head.
  const scale = Math.max(Math.abs(safeA), Math.abs(safeB)) || 1;
  const aRatio = Math.abs(safeA) / scale;
  const bRatio = Math.abs(safeB) / scale;

  const width = item.width;
  const trackW = width - 300;

  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor: p.bg || 'transparent',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    padding: '0 60px',
    boxSizing: 'border-box',
    gap: 54,
  };
  const titleStyle = {
    fontFamily: p.bodyFont,
    fontSize: 32,
    letterSpacing: '0.14em',
    color: p.muted,
    opacity: Math.min(1, enter * 1.6),
    marginBottom: 8,
  };

  const row = (label, value, ratio, color, delay) => {
    const grow = interpolate(frame, [fps * delay, fps * (delay + 0.7)], [0, 1], {
      extrapolateRight: 'clamp',
    });
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 18 }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 22 }}>
          <span style={{ fontFamily: p.bodyFont, fontSize: 34, color: p.muted }}>{label}</span>
          <span style={{ fontFamily: p.displayFont, fontSize: 62, color }}>{value}</span>
        </div>
        {/* Opacity on the track would dim the bar inside it too — the fill has to
            be an rgba colour so the bar keeps its own weight. */}
        <div style={{ width: trackW, height: 26, backgroundColor: 'rgba(138,133,124,0.18)', borderRadius: 13 }}>
          <div
            style={{
              // A 1000:1 comparison is honest but a 0.5px bar reads as a bug,
              // so the sliver keeps a floor that still looks like a sliver.
              width: Math.max(12, trackW * ratio * grow),
              height: '100%',
              backgroundColor: color,
              borderRadius: 13,
            }}
          />
        </div>
      </div>
    );
  };

  return (
    <div style={rootStyle}>
      {p.title ? <div style={titleStyle}>{p.title}</div> : null}
      {row(p.aLabel ?? '', safeA + (p.unit ?? ''), aRatio, p.muted === p.aColor ? p.ink : p.aColor, 0.15)}
      {row(p.bLabel ?? '', safeB + (p.unit ?? ''), bRatio, p.bColor, 0.45)}
    </div>
  );
};

const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = item.props;
  // The recipe is designed at 1080 wide and is handed the whole canvas, so
  // every fixed pixel value below is a design value. Without this factor a
  // 1920-wide landscape frame keeps the 1080 sizes and the word looks small in
  // a frame that is 1.8× bigger.
  const k = item.width / 1080;

  // A slam: it arrives oversized and settles, rather than growing into place.
  const enter = spring({ frame, fps, config: { damping: 18, mass: 0.7, stiffness: 150 } });
  const scale = 1.24 - 0.24 * enter;
  const opacity = Math.min(1, enter * 2.2);
  const glow = interpolate(frame, [0, fps * 0.8], [0.22, 0], { extrapolateRight: 'clamp' });

  // Two characters at 620px each is 1240px in a 1080px box: the outer strokes
  // get cropped. So the size is capped by width, and then by height — the
  // frame is 1080 tall in landscape, and a width-only cap let a two-character
  // word grow to 864px and sit on top of the burned-in captions.
  const glyphs = Array.from(String(p.text ?? ''));
  const perGlyph = glyphs.length > 0 ? (item.width / glyphs.length) * 0.9 : p.fontSize;
  // Leave the bottom band alone: burned-in captions occupy the last ~16%, and
  // the recipe's own caption needs a line under the word.
  const roomForWord = item.height * (p.caption ? 0.5 : 0.62);
  const size = Math.min(p.fontSize * k, perGlyph, roomForWord);

  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor: p.bg || 'transparent',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
  };
  const wordStyle = {
    fontFamily: p.displayFont,
    fontSize: size,
    // 0.86 collided: a 760px em box in a 654px line box overlapped the line above.
    lineHeight: 1.0,
    fontWeight: 400,
    letterSpacing: p.tracking,
    color: p.ink,
    textAlign: 'center',
    transform: 'scale(' + scale + ')',
    opacity: opacity,
    textShadow: '0 0 ' + (60 * k * glow) + 'px ' + p.accent,
  };
  // Flow below the word instead of pinning to a bottom offset: with the word
  // sized from the frame, a fixed offset lands inside the glyphs.
  const captionStyle = {
    marginTop: item.height * 0.035,
    textAlign: 'center',
    fontFamily: p.bodyFont,
    fontSize: 34 * k,
    letterSpacing: '0.3em',
    color: p.muted,
    opacity: interpolate(frame, [fps * 0.4, fps * 1.0], [0, 1], { extrapolateRight: 'clamp' }),
  };

  return (
    <div style={rootStyle}>
      <div style={wordStyle}>{p.text}</div>
      {p.caption ? <div style={captionStyle}>{p.caption}</div> : null}
    </div>
  );
};

