const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = item.props;
  // The compiler swaps the design box when the canvas is wide, and says so.
  // Same content, different arrangement: stacked top/bottom reads as a before
  // and after on a phone, but on 16:9 it is a narrow column with the right half
  // of the frame empty. Side by side is the landscape form of the same idea.
  const wide = p.landscape === true;

  const topIn = interpolate(frame, [0, fps * 0.45], [0, 1], { extrapolateRight: 'clamp' });
  const divider = interpolate(frame, [fps * 0.35, fps * 0.85], [0, 1], { extrapolateRight: 'clamp' });
  const bottomIn = interpolate(frame, [fps * 0.7, fps * 1.2], [0, 1], { extrapolateRight: 'clamp' });

  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor: p.bg || 'transparent',
    display: 'flex',
    flexDirection: wide ? 'row' : 'column',
    justifyContent: 'center',
    alignItems: wide ? 'center' : 'stretch',
    padding: wide ? '0 40px' : '0 20px',
    boxSizing: 'border-box',
  };
  const blockStyle = {
    display: 'flex',
    flexDirection: 'column',
    ...(wide ? { flex: '1 1 0', minWidth: 0 } : {}),
  };
  // In a row, the two blocks slide in from opposite sides; the vertical
  // translate that suits a stack reads as a wobble.
  const topBlockStyle = {
    ...blockStyle,
    opacity: topIn,
    transform: wide
      ? 'translateX(' + ((1 - topIn) * -30) + 'px)'
      : 'translateY(' + ((1 - topIn) * -20) + 'px)',
  };
  const bottomBlockStyle = {
    ...blockStyle,
    opacity: bottomIn,
    transform: wide
      ? 'translateX(' + ((1 - bottomIn) * 30) + 'px)'
      : 'translateY(' + ((1 - bottomIn) * 24) + 'px)',
  };
  const labelStyle = (color) => ({
    fontFamily: p.bodyFont,
    fontSize: wide ? 38 : 32,
    fontWeight: 500,
    letterSpacing: '0.28em',
    color: color,
    marginBottom: wide ? 20 : 16,
  });
  // A fixed size has to fit the longest line it might ever get, so short lines
  // come out timid. Fit to the actual text instead, capped so a three-character
  // line does not turn into a poster.
  const gutter = wide ? p.gap * 2 + 3 : 120;
  const fitSize = (text) => {
    const chars = Array.from(String(text ?? '')).length || 1;
    const inner = (item.width - gutter) / (wide ? 2 : 1);
    return Math.min(Math.round(p.fontSize * 1.7), Math.floor((inner / chars) * 0.92));
  };
  const bodySize = Math.min(fitSize(p.topText), fitSize(p.bottomText));

  const textStyle = (color) => ({
    fontFamily: p.displayFont,
    fontSize: bodySize,
    lineHeight: 1.28,
    fontWeight: 400,
    letterSpacing: '-0.01em',
    color: color,
    whiteSpace: 'pre-wrap',
  });
  // A short horizontal rule is the stacked form of "these two are the same
  // kind of thing"; the row form is a vertical one between the columns.
  const dividerStyle = wide
    ? {
      width: 3,
      alignSelf: 'stretch',
      margin: '6% ' + p.gap + 'px',
      backgroundColor: p.muted,
      opacity: 0.45 * divider,
    }
    : {
      height: 3,
      width: (p.dividerWidth * divider) + 'px',
      backgroundColor: p.muted,
      opacity: 0.45,
      margin: p.gap + 'px 0',
    };

  return (
    <div style={rootStyle}>
      <div style={topBlockStyle}>
        <div style={labelStyle(p.muted)}>{p.topLabel}</div>
        {/* Empty topColor means "derive from muted": that way the compiler's
             over-footage correction reaches the dimmed line too. */}
        <div style={textStyle(p.topColor || p.muted)}>{p.topText}</div>
      </div>
      <div style={dividerStyle} />
      <div style={bottomBlockStyle}>
        <div style={labelStyle(p.accent)}>{p.bottomLabel}</div>
        <div style={textStyle(p.bottomColor)}>{p.bottomText}</div>
      </div>
    </div>
  );
};

const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = item.props;

  const steps = (Array.isArray(p.steps) ? p.steps : []).slice(0, 4);
  const labels = Array.isArray(p.labels) ? p.labels : [];
  if (steps.length < 2) return null;

  const width = item.width;
  const gap = 74;
  const boxW = (width - 120 - gap * (steps.length - 1)) / steps.length;

  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor: p.bg || 'transparent',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    padding: '0 60px',
    boxSizing: 'border-box',
    gap: 40,
  };

  return (
    <div style={rootStyle}>
      {p.title ? (
        <div style={{ fontFamily: p.bodyFont, fontSize: 30, letterSpacing: '0.14em', color: p.muted }}>
          {p.title}
        </div>
      ) : null}
      <div style={{ display: 'flex', alignItems: 'center' }}>
        {steps.map((step, index) => {
          const enter = spring({
            frame: frame - Math.round(index * fps * 0.18),
            fps,
            config: { damping: 18, mass: 0.6, stiffness: 150 },
          });
          // Arrows draw left to right, so the chain reads as a sequence rather
          // than as three boxes that happen to be next to each other.
          const arrow = interpolate(
            frame,
            [fps * (0.25 + index * 0.18), fps * (0.55 + index * 0.18)],
            [0, 1],
            { extrapolateRight: 'clamp' },
          );
          return (
            <div key={index} style={{ display: 'flex', alignItems: 'center' }}>
              <div
                style={{
                  width: boxW,
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: 16,
                  opacity: Math.min(1, enter * 1.4),
                  transform: 'translateY(' + ((1 - enter) * 20) + 'px)',
                }}
              >
                {labels[index] ? (
                  <div style={{ fontFamily: p.bodyFont, fontSize: 24, letterSpacing: '0.2em', color: p.accent }}>
                    {labels[index]}
                  </div>
                ) : null}
                <div
                  style={{
                    fontFamily: p.displayFont,
                    fontSize: p.fontSize,
                    lineHeight: 1.25,
                    color: p.ink,
                    textAlign: 'center',
                  }}
                >
                  {step}
                </div>
              </div>
              {index < steps.length - 1 ? (
                <svg width={gap} height={40} viewBox={`0 0 ${gap} 40`} style={{ flex: '0 0 auto' }}>
                  <line
                    x1={6} y1={20} x2={6 + (gap - 22) * arrow} y2={20}
                    stroke={p.accent} strokeWidth={5} strokeLinecap="round"
                  />
                  {arrow > 0.85 ? (
                    <path
                      d={`M${gap - 22} 10 L${gap - 6} 20 L${gap - 22} 30`}
                      fill="none" stroke={p.accent} strokeWidth={5}
                      strokeLinecap="round" strokeLinejoin="round"
                    />
                  ) : null}
                </svg>
              ) : null}
            </div>
          );
        })}
      </div>
    </div>
  );
};

const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = item.props;

  // A small inline set, drawn as paths so the recipe stays one file and needs no
  // asset lookup. `icons` picks from these by name; an unknown name falls back to
  // a dot, which still reads as "an item" rather than as a hole.
  const PATHS = {
    clock: 'M12 3a9 9 0 100 18 9 9 0 000-18zm0 4v5l3.5 2',
    growth: 'M3 17l5-5 4 3 6-8M14 7h5v5',
    people: 'M8 11a3 3 0 100-6 3 3 0 000 6zm8 0a3 3 0 100-6 3 3 0 000 6zM2 20c0-3 3-5 6-5s6 2 6 5M14 15c3 0 6 2 6 5',
    coin: 'M12 3a9 9 0 100 18 9 9 0 000-18zM12 7.5a4.5 4.5 0 100 9 4.5 4.5 0 000-9z',
    check: 'M4 12l5 5L20 6',
    arrow: 'M4 12h15M13 6l6 6-6 6',
    star: 'M12 3l2.7 5.6 6.3.9-4.5 4.4 1 6.1-5.5-2.9-5.5 2.9 1-6.1L3 9.5l6.3-.9z',
    shield: 'M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z',
  };

  const items = (Array.isArray(p.items) ? p.items : []).slice(0, 4);
  const icons = Array.isArray(p.icons) ? p.icons : [];
  if (!items.length) return null;

  const width = item.width;
  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor: p.bg || 'transparent',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
