            config: { damping: 18, mass: 0.6, stiffness: 150 },
          });
          const path = PATHS[icons[index]] ?? null;
          return (
            <div
              key={index}
              style={{
                width: (width - 120) / items.length - 18,
                display: 'flex',
                flexDirection: 'column',
