              </svg>
              <div
                style={{
                  fontFamily: p.displayFont,
                  fontSize: p.fontSize,
                  color: p.ink,
                  textAlign: 'center',
                  lineHeight: 1.25,
                }}
              >
                {label}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
