const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = item.props;
  // Wide canvas: centred and larger. A left-aligned measure that is right for a
  // 900px card leaves two thirds of a 1920px frame empty, and at the portrait
  // size the line breaks wherever it runs out of width rather than where the
  // sentence wants to pause.
  const wide = p.landscape === true;

  // A quote is a place to breathe: the reveal is slow and the motion is small.
  const mark = interpolate(frame, [0, fps * 0.5], [0, 1], { extrapolateRight: 'clamp' });
  const body = interpolate(frame, [fps * 0.3, fps * 1.1], [0, 1], { extrapolateRight: 'clamp' });
  const credit = interpolate(frame, [fps * 1.0, fps * 1.7], [0, 1], { extrapolateRight: 'clamp' });

  // Fit the type to the sentence instead of fixing it: a 12-character line and a
  // 32-character line should both fill the card. Two lines is the target on a
  // wide canvas — one long line reads as a ticker, four reads as a paragraph.
  const chars = Array.from(String(p.text ?? '')).length || 1;
  const perLine = chars <= 12 ? chars : Math.ceil(chars / 2);
  const inner = item.width * 0.86;
  const fit = Math.floor((inner / perLine) * 0.95);
  // Portrait keeps its authored size and simply wraps; the fit is what makes a
  // wide card use its width instead of breaking the sentence in half.
  const size = wide ? Math.min(Math.round(p.fontSize * 1.6), fit) : p.fontSize;

  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor: p.bg || 'transparent',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    alignItems: wide ? 'center' : 'stretch',
    textAlign: wide ? 'center' : 'left',
    padding: wide ? '0 7%' : '0 20px',
    boxSizing: 'border-box',
  };
  // A rule rather than a “ glyph: the CJK quotation mark renders as two small
  // slashes in this face and reads as a typo.
  const markStyle = {
    width: (wide ? 120 : 96) * mark,
    height: 6,
    borderRadius: 3,
    backgroundColor: p.accent,
    marginBottom: wide ? 44 : 34,
  };
  const bodyStyle = {
    marginTop: 18,
    fontFamily: p.displayFont,
    fontSize: size,
    lineHeight: wide ? 1.34 : 1.42,
    fontWeight: 400,
    letterSpacing: '-0.01em',
    color: p.ink,
    whiteSpace: 'pre-wrap',
    // 20 characters at 58px in an 860px card wraps as 19 + 1, leaving a single
    // orphan character on the second line. Balance the lines instead.
    textWrap: 'balance',
    opacity: body,
    transform: 'translateY(' + ((1 - body) * 20) + 'px)',
  };
  const creditStyle = {
    marginTop: wide ? 42 : 34,
    fontFamily: p.bodyFont,
    fontSize: wide ? 34 : 30,
    letterSpacing: '0.16em',
    color: p.muted,
    opacity: credit,
  };

  return (
    <div style={rootStyle}>
      <div style={markStyle} />
      <div style={bodyStyle}>{p.text}</div>
      {p.author ? <div style={creditStyle}>{p.author}{p.source ? ' · ' + p.source : ''}</div> : null}
    </div>
  );
};

const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = item.props;

  const parts = (Array.isArray(p.parts) ? p.parts : []).slice(0, 4);
  const values = (Array.isArray(p.values) ? p.values : [])
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value) && value >= 0)
    .slice(0, parts.length);
  if (parts.length < 2 || values.length !== parts.length) return null;

  const total = values.reduce((sum, value) => sum + value, 0) || 1;
  const shares = values.map((value) => value / total);

  // Each segment grows into place in turn, so the bar reads as parts adding up
  // rather than as a finished chart that faded in.
  const grow = (index) => interpolate(
    frame,
    [fps * (0.15 + index * 0.14), fps * (0.6 + index * 0.14)],
    [0, 1],
    { extrapolateRight: 'clamp' },
  );

  const width = item.width;
  const trackW = width - 120;
  // One accent, one ink, and muted greys for the rest: four saturated colours
  // would fight each other and none of them would read as "the important one".
  // The fourth colour has to survive on a near-black card: a dark grey at low
  // alpha disappears into the background and the segment looks like a gap.
  const fills = [p.accent, p.ink, p.muted, 'rgba(242,239,233,0.32)'];

  const rootStyle = {
    position: 'absolute',
    inset: 0,
    backgroundColor: p.bg || 'transparent',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    padding: '0 60px',
    boxSizing: 'border-box',
    gap: 50,
  };

  return (
    <div style={rootStyle}>
      {p.title ? (
        <div style={{ fontFamily: p.bodyFont, fontSize: 30, letterSpacing: '0.14em', color: p.muted }}>
          {p.title}
        </div>
      ) : null}
      <div style={{ display: 'flex', width: trackW, height: 76, borderRadius: 10, overflow: 'hidden' }}>
        {shares.map((share, index) => (
          <div
            key={index}
            style={{
              width: trackW * share * grow(index),
              height: '100%',
              backgroundColor: fills[index % fills.length],
            }}
          />
        ))}
      </div>
      <div style={{ display: 'flex', width: trackW, gap: 28, flexWrap: 'wrap' }}>
        {parts.map((part, index) => (
          <div
            key={index}
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 12,
              opacity: grow(index),
            }}
          >
            <span
              style={{
                width: 20,
                height: 20,
                borderRadius: 4,
                backgroundColor: fills[index % fills.length],
                flex: '0 0 auto',
              }}
            />
            <span style={{ fontFamily: p.bodyFont, fontSize: 34, color: p.muted }}>{part}</span>
            <span style={{ fontFamily: p.displayFont, fontSize: 38, color: p.ink }}>
              {values[index] + (p.unit ?? '')}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};

